changeSet.sql:
update wf_procedure set tasks=regexp_replace(tasks, E'[\\n\\r\\f\\u000B\\u0085\\u2028\\u2029]+', '\n', 'g' );
update content set attributes=regexp_replace(attributes, E'[\\n\\r\\f\\u000B\\u0085\\u2028\\u2029]+', '\n', 'g' );
update datasetmember set attributes=regexp_replace(attributes, E'[\\n\\r\\f\\u000B\\u0085\\u2028\\u2029]+', '\n', 'g' );

update wf_procedure set tasks=replace(tasks, '\''', '\"');
update content set attributes=replace(attributes, '\''', '\"');
update datasetmember set attributes=replace(attributes, '\''', '\"');

create table if not exists kb_form_template (
	form_id				bigint references kb_form(id) on delete cascade,
	contenttemplate_id	bigint references kb_contenttemplate(id) on delete cascade
);
